module pe(
    input clk, input rst, input [31:0] a, input [31:0] b,
    output reg [31:0] c
);
    // TODO: implement a parallel multiplier and accumulator using registers and always block
    // TODO: remove the following code once you implement this module
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            c <= 32'b0;
        end else begin
            c <= c + a * b;
        end
    end
endmodule
